 ('mc', 5, 'musab', 'İlk öğretmen', 'h', 'Medine’ye İslam’ı öğretmek üzere gönderilen ilk sahabe kimdir?', 'Mus‘ab b. Umeyr', ['Hâlid b. Velîd', 'Amr b. Âs', 'Ebû Süfyân'], 'Birinci Akabe biatından sonra Mus‘ab b. Umeyr Medine’ye öğretmen olarak gönderildi.'),
 ('mc', 5, 'hicret_yil', 'Hicret yılı', 'e', 'Hicret miladi hangi yılda gerçekleşti?', '622', ['571', '610', '632'], 'Hz. Peygamber 622 yılında Mekke’den Medine’ye hicret etti.'),
 ('mc', 5, 'ali_yatak', 'Hicret gecesi', 'm', 'Hicret gecesi Hz. Peygamber’in yatağına kim yattı?', 'Hz. Ali', ['Hz. Ebû Bekir', 'Hz. Ömer', 'Hz. Bilâl'], 'Hz. Ali, emanetleri sahiplerine vermek üzere Mekke’de kaldı ve o gece Peygamber’in yatağına yattı.'),
 ('mc', 5, 'sevr', 'Sevr mağarası', 'm', 'Hz. Peygamber ve Hz. Ebû Bekir hicret yolunda üç gün nerede saklandılar?', 'Sevr mağarasında', ['Hira mağarasında', 'Uhud dağında', 'Kâbe’de'], 'Müşrikler mağaranın ağzına kadar geldi ama onları göremedi.'),
 ('mc', 5, 'tevbe40', 'Üzülme', 'm', 'Mağarada endişelenen Hz. Ebû Bekir’e Hz. Peygamber ne dedi?', '“Üzülme, Allah bizimle beraberdir.”', ['“Hemen kaçalım.”', '“Biz yakalandık.”', '“Silahlarını hazırla.”'], 'Tevbe 9:40: “Üzülme, Allah bizimle beraberdir.”'),
 ('mc', 5, 'kuba', 'Kuba', 'm', 'Hz. Peygamber Medine’ye varmadan önce yaptırdığı ilk mescit hangisidir?', 'Kuba Mescidi', ['Mescid-i Aksâ', 'Mescid-i Haram', 'Mescid-i Kıbleteyn'], 'Kuba Mescidi, İslam’da inşa edilen ilk mesciddir.'),
 ('mc', 5, 'hicri_takvim', 'Hicrî takvim', 'm', 'Hicrî takvimin başlangıcı hangi olaydır?', 'Hicret', ['Hz. Peygamber’in doğumu', 'İlk vahiy', 'Mekke’nin fethi'], 'Hz. Ömer döneminde hicret, takvimin başlangıcı kabul edildi.'),
 ('tf', 5, 'dar_nedve', 'Suikast planı', 'h', 'Müşrikler Dârünnedve’de toplanarak Hz. Peygamber’i öldürmeye karar verdiler.', True, 'Her kabileden bir genç seçilerek suikast planlandı; Allah elçisini korudu (Enfâl 8:30).'),
 ('tf', 5, 'ebubekir_yol', 'Yol arkadaşı', 'e', 'Hicrette Hz. Peygamber’in yol arkadaşı Hz. Ebû Bekir’di.', True, 'Hz. Ebû Bekir hicret yolculuğunda Hz. Peygamber’in arkadaşıydı.'),
 ('sc', 5, 'sc_emanet', 'Emanetlerin iadesi', 'm', 'Hz. Peygamber hicret ederken kendisine düşman olanların emanetlerini ne yaptı?', 'Hz. Ali aracılığıyla sahiplerine iade ettirdi', ['Yanında götürdü', 'Fakirlere dağıttı', 'Yok etti'], 'Düşmanlarına bile emanet konusunda adaletli davrandı.'),
 ('sc', 5, 'sc_tevekkul', 'Tevekkül', 'm', 'Sevr mağarasında müşrikler tam kapıdayken Hz. Peygamber’in tutumundan hangi ders çıkar?', 'Tedbir aldıktan sonra Allah’a güvenmek (tevekkül)', ['Hiç tedbir almamak', 'Paniğe kapılmak', 'Teslim olmak'], 'Yolu gizli tuttular, mağaraya saklandılar; sonra Allah’a güvendiler.'),
 ('fb', 5, 'fb_yesrib', 'Medine’nin eski adı', 'm', 'Medine’nin hicretten önceki adı ___ idi.', 'Yesrib', ['Taif', 'Hayber', 'Tebük'], 'Hicretten sonra şehir “Medînetü’n-Nebî”, yani Peygamber şehri olarak anıldı.'),
 ('fb', 5, 'fb_suraka', 'Takipçi', 'h', 'Hicret yolunda Hz. Peygamber’i yakalamak için peşine düşen ama sonra vazgeçen kişi ___ b. Mâlik’tir.', 'Sürâka', ['Ebû Süfyân', 'İkrime', 'Ümeyye'], 'Sürâka’nın atının ayakları kuma battı; o da vazgeçip geri döndü.'),
 ('mi', 5, 'mi_medine_karsilama', 'Karşılama', 'e', 'Medineliler Hz. Peygamber’i büyük bir ___ karşıladılar.', 'sevinçle', ['öfkeyle', 'korkuyla', 'kayıtsızlıkla'], 'Medineliler onu coşkuyla karşıladı.'),
 ('mt', 5, 'hicret_esle', 'Hicret yolculuğu', 'm', 'Hicretle ilgili kavramları eşleştir:', [('Sevr', 'Üç gün saklanılan mağara'), ('Kuba', 'İlk inşa edilen mescit'), ('Yesrib', 'Medine’nin eski adı'), ('Dârünnedve', 'Müşriklerin toplantı yeri')], 'Hicretin önemli yer ve kavramları.'),

